            // `default: on-hold` written next to it. The default must be the
            // typed member both when the model is built without the argument and
            // when the payload omits the key; an explicit value still wins.
            val built =
                com.example.petstore.models
                    .StockItem(priority = com.example.petstore.models.Priority.NUMBER_1)
            assertEquals(com.example.petstore.models.Availability.ON_HOLD, built.availability)

            val decoded = serializer.deserialize<com.example.petstore.models.StockItem>("{\"priority\":1}")
            assertNotNull(decoded)
