        @Test
        @DisplayName("bhvModels021 each member of an integer-backed enum carries its declared number as its value")
        fun bhvModels021EachIntegerEnumMemberCarriesItsDeclaredNumber() {
            for (member in com.example.petstore.models.Priority.entries) {
                assertEquals(member.name.removePrefix("NUMBER_").toInt(), member.value, member.name)
            }
        }

        @Test
        @DisplayName(
            "bhvSerializationobject093 integer-backed enum (Priority) round-trips as a " +
                "JSON NUMBER, not a string",
        )
        fun integerBackedEnumSerializesAsNumber() {
            // Priority is an integer-backed enum (enum: 1, 2, 3). Seven SDKs
            // hard-coded the int-enum path as String-backed; the corrected
            // Kotlin Serializer encodes the backing int via encodeInt, so the
            // wire form is a bare JSON number (2), never the quoted string
            // ("2"). Carried on a StockItem.priority field (required).
            val item =
                com.example.petstore.models
                    .StockItem(priority = com.example.petstore.models.Priority.NUMBER_2)
            val json = serializer.serialize(item)
            assertTrue(json.contains("\"priority\":2"), "priority must serialize as a JSON number, got: $json")
            assertFalse(json.contains("\"priority\":\"2\""), "priority must NOT be a quoted string, got: $json")

            // Deserialize the number back into the enum member.
            val decoded = serializer.deserialize<com.example.petstore.models.StockItem>("{\"priority\":2}")
            assertNotNull(decoded)
            assertEquals(com.example.petstore.models.Priority.NUMBER_2, decoded!!.priority)
        }

        @Test
        @DisplayName("bhvSerializationobject171 type:number Decimal is an UNQUOTED number, round-trips")
        fun decimalNumberFieldSerializesAsUnquotedNumber() {
            // weightKg is a bare `type: number` (no format) property modelled
            // as java.math.BigDecimal with the contextual BigDecimalSerializer.
            // The spec types it as a JSON number, so the wire form of a
            // non-integer value (1.5) must be a bare number token (1.5), never
            // a quoted string ("1.5"). BigDecimalSerializer emits the canonical
            // plain string through JsonUnquotedLiteral, preserving arbitrary
            // precision while staying a JSON Number.
            val pet =
                com.example.petstore.models.Pet(
                    name = "fido",
                    photoUrls = setOf("http://example.com/fido.png"),
                    weightKg = java.math.BigDecimal("1.5"),
                )
            val json = serializer.serialize(pet)
            assertTrue(json.contains("\"weightKg\":1.5"), "weightKg must serialize as a JSON number, got: $json")
            assertFalse(json.contains("\"weightKg\":\"1.5\""), "weightKg must NOT be a quoted string, got: $json")

            // It must survive a serialize -> deserialize round trip as a
            // BigDecimal carrying the same numeric value.
            val decoded = serializer.deserialize<com.example.petstore.models.Pet>(json)
            assertNotNull(decoded)
            assertEquals(0, java.math.BigDecimal("1.5").compareTo(decoded!!.weightKg))
        }

        @Test
        @DisplayName("bhvSerializationobject002 type:number Decimal is exact: no double round trip and no exponent notation")
        fun decimalNumberFieldIsExactAndPlain() {
            // D83/F1162: a bare `type: number` keeps every digit and is written in plain
            // notation, whatever notation the wire value used.
            val rows =
                listOf(
                    "0.1234567890123456789" to "0.1234567890123456789",
                    "12345678901234567890.5" to "12345678901234567890.5",
                    "1.50" to "1.50",
                    "1E-8" to "0.00000001",
                    "1E+20" to "100000000000000000000",
                )
            for ((wire, written) in rows) {
                val decoded =
                    serializer.deserialize<com.example.petstore.models.Pet>(
                        "{\"name\":\"f\",\"photoUrls\":[],\"weightKg\":$wire}",
                    )
                assertNotNull(decoded, wire)
                assertEquals(0, java.math.BigDecimal(wire).compareTo(decoded!!.weightKg), wire)
                val json = serializer.serialize(decoded)
                assertTrue(json.contains("\"weightKg\":$written"), "$wire must be written as $written, got: $json")
                assertFalse(Regex("[0-9][eE][+-]?[0-9]").containsMatchIn(json), "no exponent notation expected, got: $json")
            }
        }

        @Test
        @DisplayName("bhvSerializationobject109 non-lowercase string enum (Availability) round-trips with wire casing preserved")
        fun nonLowercaseStringEnumPreservesWireCasing() {
            // Availability is a non-lowercase string enum (Available, Sold,
            // on-hold). The @SerialName wire form must be preserved verbatim,
            // including the sanitized "on-hold" variant whose hyphen is not a
            // legal identifier character.
            val available =
                serializer.serialize(
                    com.example.petstore.models.StockItem(
                        priority = com.example.petstore.models.Priority.NUMBER_1,
                        availability = com.example.petstore.models.Availability.AVAILABLE,
                    ),
                )
            assertTrue(available.contains("\"availability\":\"Available\""), "expected Available casing, got: $available")

            val onHold =
                serializer.serialize(
                    com.example.petstore.models.StockItem(
                        priority = com.example.petstore.models.Priority.NUMBER_1,
                        availability = com.example.petstore.models.Availability.ON_HOLD,
                    ),
                )
            assertTrue(onHold.contains("\"availability\":\"on-hold\""), "expected on-hold wire form, got: $onHold")

            // Deserializing "Available" yields the right member.
            val decoded =
                serializer.deserialize<com.example.petstore.models.StockItem>(
                    "{\"priority\":1,\"availability\":\"Sold\"}",
                )
            assertNotNull(decoded)
            assertEquals(com.example.petstore.models.Availability.SOLD, decoded!!.availability)
        }

        @Test
        @DisplayName("bhvSerializationobject059 unknown Availability wire value is rejected on deserialize")
        fun unknownAvailabilityValueRejected() {
            // An undeclared enum value must fail loud rather than coerce to null
            // or a default.
            assertThrows(SerializationException::class.java) {
                serializer.deserialize<com.example.petstore.models.StockItem>(
                    "{\"priority\":1,\"availability\":\"out-of-stock\"}",
                )
            }
        }

        @Test
        @DisplayName("bhvSerializationobject104 colliding schema names (Error, Result) keep their wire keys through EdgeCases")
        fun collidingSchemaNamesRoundTrip() {
            // F1131/D45: lastError and outcome decode and re-encode under their own keys.
            val wire = "{\"lastError\":{\"code\":7,\"message\":\"boom\"},\"outcome\":{\"ok\":true}}"
            val decoded = serializer.deserialize<com.example.petstore.models.EdgeCases>(wire)
            assertNotNull(decoded)
            assertEquals(7, decoded!!.lastError!!.code)
            assertEquals("boom", decoded.lastError!!.message)
            assertEquals(true, decoded.outcome!!.ok)
            assertEquals(
                kotlinx.serialization.json.Json
                    .parseToJsonElement(wire),
                kotlinx.serialization.json.Json
                    .parseToJsonElement(serializer.serialize(decoded)),
            )
        }

        @Test
        @DisplayName("bhvSerializationobject161 enum members with non-identifier wire values (Separator) decode to distinct constants")
        fun separatorEnumRoundTrip() {
            // F1124: ' ', '@@', 'a-b' and 'a_b' sanitise to empty or colliding identifiers.
            val members = mutableSetOf<Any>()
            for (wire in listOf(" ", "@@", "a-b", "a_b")) {
                val decoded = serializer.deserialize<com.example.petstore.models.EdgeCases>("{\"separator\":\"$wire\"}")
                assertNotNull(decoded, wire)
                members.add(decoded!!.separator!!)
                assertEquals(wire, decoded.separator!!.value)
                assertTrue(serializer.serialize(decoded).contains("\"separator\":\"$wire\""), wire)
            }
            assertEquals(4, members.size)
        }

        @Test
        @DisplayName("bhvSerializationobject115 a contentEncoding property (PetPassport.biometricChip) is a base64 byte field")
        fun contentEncodedPropertyIsBase64Bytes() {
            // F1116: normalised to format: byte, so it decodes from and encodes to standard base64.
            val decoded = serializer.deserialize<com.example.petstore.models.PetPassport>("{\"biometricChip\":\"AQID\"}")
