        fun additionalPropertiesRoundTripAtTopLevel() {
            // Metadata declares `additionalProperties: true` and carries the
            // extras in a @Transient map. An extra JSON key seen on deserialize
            // must be captured and re-serialized as a TOP-LEVEL member, never
            // nested under an "additionalProperties" wrapper key.
            val decoded =
                serializer.deserialize<com.example.petstore.models.Metadata>(
