            assertEquals("gold", decoded.additionalProperties["tier"])

            val reserialized = serializer.serialize(decoded)
            assertTrue(reserialized.contains("\"region\":\"emea\""), "extra key must re-emit at top level, got: $reserialized")
            assertTrue(reserialized.contains("\"tier\":\"gold\""), "extra key must re-emit at top level, got: $reserialized")
            assertFalse(
                reserialized.contains("\"additionalProperties\""),
                "extras must NOT nest under an additionalProperties key, got: $reserialized",
