            assertEquals(java.time.Duration.ofSeconds(315_576_000_000L), atBound!!.retryAfter)
            val negAtBound = serializer.deserialize<com.example.petstore.models.EdgeCases>("{\"retryAfter\":\"-315576000000s\"}")
            assertEquals(java.time.Duration.ofSeconds(-315_576_000_000L), negAtBound!!.retryAfter)
            for (text in listOf("315576000001s", "-315576000001s", "315576000000.000000001s")) {
                assertThrowsExactly(SerializationException::class.java) {
                    serializer.deserialize<com.example.petstore.models.EdgeCases>("{\"retryAfter\":\"$text\"}")
                }
            }
        }

        @Test
        @DisplayName("bhvSerializationobject113 parses a negative protobuf-JSON duration of whole seconds")
        fun negativeWholeSecondProtobufDurationParses() {
            val edge = serializer.deserialize<com.example.petstore.models.EdgeCases>("{\"retryAfter\":\"-90s\"}")
            assertEquals(java.time.Duration.ofSeconds(-90), edge!!.retryAfter)
        }

        @Test
        @DisplayName("bhvSerializationobject080 format:duration that is malformed or overflows raises the SDK SerializationException")
        fun malformedOrOverflowingDurationRaisesSerializationException() {
            // Neither kotlinx's SerializationException nor a raw
            // NumberFormatException may escape: both become the SDK's own
            // SerializationException, which a catch on the SDK root sees.
            for (wire in listOf("90", "1.5m", "99999999999999999999s")) {
                val ex =
                    assertThrowsExactly(com.example.petstore.errors.SerializationException::class.java) {
                        serializer.deserialize<com.example.petstore.models.EdgeCases>("{\"retryAfter\":\"$wire\"}")
                    }
                assertTrue(ex is OpenAPIException, "must extend the SDK root, was: $ex")
            }
        }

        @Test
        @DisplayName("bhvSerializationobject184 an ISO-8601 duration string is rejected")
        fun iso8601DurationStringIsRejected() {
            val ex =
                assertThrowsExactly(com.example.petstore.errors.SerializationException::class.java) {
                    serializer.deserialize<com.example.petstore.models.EdgeCases>("{\"retryAfter\":\"PT1H\"}")
                }
            assertTrue(ex is OpenAPIException, "must extend the SDK root, was: $ex")
        }
    }

