        @Test
        @DisplayName("bhvSerialization026 a JSON object decodes to a map of its typed values, and an empty object to an empty map")
        fun jsonObjectDecodesToAMapOfTypedValues() {
            assertEquals(mapOf("a" to "b"), serializer.deserialize<Map<String, String>>("{\"a\":\"b\"}"))
            assertEquals(emptyMap<String, String>(), serializer.deserialize<Map<String, String>>("{}"))
        }

        @Test
        @DisplayName("bhvSerialization028 a JSON value of the wrong kind for a model, list or map is refused")
        fun wrongKindForModelListOrMapIsRefused() {
            assertThrows(SerializationException::class.java) { serializer.deserialize<com.example.petstore.models.Pet>("[]") }
            assertThrows(SerializationException::class.java) { serializer.deserialize<List<Int>>("{}") }
            assertThrows(SerializationException::class.java) { serializer.deserialize<Map<String, Int>>("[]") }
        }

        @Test
        @DisplayName("bhvSerialization029 a JSON value of the wrong kind for a scalar or enum field is refused")
        fun wrongKindForScalarOrEnumIsRefused() {
            assertThrows(SerializationException::class.java) {
                serializer.deserialize<com.example.petstore.models.Pet>("{\"name\":\"dog\",\"photoUrls\":[],\"status\":3}")
            }
            assertThrows(SerializationException::class.java) {
                serializer.deserialize<com.example.petstore.models.Order>("{\"quantity\":\"3\"}")
            }
        }

        @Test
        @DisplayName("bhvSerialization030 a date-time field accepts only a string, so a number, boolean or array is refused")
        fun dateTimeFieldAcceptsOnlyAString() {
            for (value in listOf("1700000000", "true", "[]")) {
                assertThrows(SerializationException::class.java) {
                    serializer.deserialize<com.example.petstore.models.Order>("{\"shipDate\":$value}")
                }
            }
        }

        @Test
        @DisplayName("bhvSerialization031 a whole number at the 32-bit and 64-bit limits decodes exactly")
        fun wholeNumbersAtTheLimitsDecodeExactly() {
            assertEquals(Int.MIN_VALUE, serializer.deserialize<com.example.petstore.models.Order>("{\"quantity\":-2147483648}")!!.quantity)
            assertEquals(Long.MIN_VALUE, serializer.deserialize<com.example.petstore.models.Order>("{\"id\":-9223372036854775808}")!!.id)
        }

        @Test
        @DisplayName("bhvSerialization032 an integer field refuses a number written with a fraction or exponent even when whole")
        fun integerRefusesFractionOrExponent() {
            for (value in listOf("2.0", "1e2")) {
                assertThrows(SerializationException::class.java) {
                    serializer.deserialize<com.example.petstore.models.Order>("{\"quantity\":$value}")
                }
            }
        }

        @Test
        @DisplayName("bhvSerialization033 each leaf of an integer array must be a plain integer in range")
        fun integerArrayLeavesMustBePlainIntegersInRange() {
            for (body in listOf("[[1.0]]", "[[3000000000]]", "[[true]]")) {
                assertThrows(SerializationException::class.java) {
                    serializer.deserialize<List<List<Int>>>(body)
                }
            }
        }

        @Test
        @DisplayName("bhvSerialization034 a floating-point field decodes a finite number to its exact numeric value")
        fun floatingPointDecodesFiniteNumbersExactly() {
            assertEquals(0.1, serializer.deserialize<Double>("0.1"))
            assertEquals(-3.0, serializer.deserialize<Double>("-3"))
        }

        @Test
        @DisplayName("bhvSerialization035 the non-standard NaN and Infinity literals are refused when decoded")
        fun nanAndInfinityLiteralsAreRefused() {
            for (body in listOf("NaN", "Infinity", "-Infinity")) {
                assertThrows(SerializationException::class.java) { serializer.deserialize<Double>(body) }
            }
        }

        @Test
        @DisplayName("bhvSerialization036 a whole-number floating-point value is written with a decimal point")
        fun wholeFloatingPointIsWrittenWithDecimalPoint() {
            assertEquals("1.0", serializer.serialize(1.0))
        }

        @Test
        @DisplayName("bhvSerialization037 a decimal number is written with every significant digit")
        fun decimalIsWrittenWithEverySignificantDigit() {
            assertEquals(
                "12345678901234567.890123",
                serializer.serialize(java.math.BigDecimal("12345678901234567.890123")),
            )
        }

        @Test
        @DisplayName("bhvSerialization038 a date-time with digits finer than a millisecond is truncated, never rounded up")
        fun subMillisecondDateTimeIsTruncated() {
            val dt = OffsetDateTime.parse("2024-01-01T12:30:45.123999+00:00")
            assertEquals("2024-01-01T12:30:45.123+00:00", serializer.stringify(dt))
        }

        @Test
        @DisplayName("bhvSerialization039 a date-time is read from any RFC 3339 spelling to the same instant")
        fun rfc3339SpellingsDecodeToTheSameInstant() {
            val z = serializer.deserialize<OffsetDateTime>("\"2024-01-01T12:30:45Z\"")
            val offset = serializer.deserialize<OffsetDateTime>("\"2024-01-01T12:30:45+00:00\"")
            val fraction = serializer.deserialize<OffsetDateTime>("\"2024-01-01T12:30:45.000Z\"")
            assertEquals(z!!.toInstant(), offset!!.toInstant())
            assertEquals(z.toInstant(), fraction!!.toInstant())
        }

        @Test
        @DisplayName("bhvSerialization041 a time string in hours, minutes and seconds parses to a time with those fields")
        fun timeStringParsesToItsFields() {
            assertEquals(java.time.LocalTime.of(11, 22, 33), serializer.deserialize<java.time.LocalTime>("\"11:22:33\""))
        }

        @Test
        @DisplayName("bhvSerialization042 a date-only string is passed through exactly as given")
        fun dateOnlyStringIsPassedThroughExactly() {
            assertEquals(LocalDate.of(2024, 2, 29), serializer.deserialize<LocalDate>("\"2024-02-29\""))
            assertEquals("2024-02-29", serializer.stringify(LocalDate.of(2024, 2, 29)))
        }

        @Test
        @DisplayName("bhvSerialization043 a time of day is written as hours, minutes and seconds")
        fun timeOfDayIsWrittenAsHoursMinutesSeconds() {
            assertEquals("09:05:07", serializer.stringify(java.time.LocalTime.of(9, 5, 7)))
        }

        @Test
        @DisplayName("bhvSerialization045 a malformed time or duration string is refused rather than decoded to a wrong value")
        fun malformedTimeOrDurationIsRefused() {
            assertThrows(SerializationException::class.java) {
                serializer.deserialize<java.time.LocalTime>("\"25:00:00\"")
            }
            assertThrows(SerializationException::class.java) {
                serializer.deserialize<java.time.Duration>("\"ten seconds\"")
            }
        }

        @Test
        @DisplayName("bhvSerialization046 a duration's fractional seconds use the shortest group of three, six or nine digits")
        fun durationFractionUsesShortestGroup() {
            assertEquals("1.500s", serializer.stringify(java.time.Duration.ofMillis(1500)))
            assertEquals("1.500000001s", serializer.stringify(java.time.Duration.ofNanos(1500000001)))
        }

        @Test
        @DisplayName("bhvSerialization048 a duration written on its own is its protobuf-JSON seconds string")
        fun durationWrittenOnItsOwnIsSecondsString() {
            assertEquals("90s", serializer.stringify(java.time.Duration.ofSeconds(90)))
        }

        @Test
        @DisplayName("bhvSerialization050 a property whose name begins with a digit reads and writes under its exact wire name")
        fun digitLeadingPropertyUsesItsWireName() {
            val model = serializer.deserialize<DigitLeadingName>("{\"2fa\":\"code\"}")
            assertEquals("code", model!!.twoFa)
            assertEquals("{\"2fa\":\"code\"}", serializer.serialize(model))
        }

        @Test
        @DisplayName("bhvSerialization061 slash, angle brackets, ampersand and non-ASCII text are written literally")
        fun slashAngleAmpersandAndNonAsciiAreLiteral() {
            assertEquals("{\"k\":\"a/<b>&é\"}", serializer.serialize(mapOf("k" to "a/<b>&é")))
        }

        @Test
        @DisplayName("bhvSerialization064 a collection of unique values is written as a JSON array of its members")
        fun uniqueCollectionIsWrittenAsArray() {
            assertEquals("[\"a\",\"b\"]", serializer.serialize(linkedSetOf("a", "b")))
        }

        @Test
        @DisplayName("bhvSerialization065 a null inside an array or map of plain or timestamp values is kept as null")
        fun nullInsideContainersIsKeptAsNull() {
            assertEquals(listOf("a", null), serializer.deserialize<List<String?>>("[\"a\",null]"))
            assertEquals(mapOf("a" to null), serializer.deserialize<Map<String, OffsetDateTime?>>("{\"a\":null}"))
        }

        @Test
        @DisplayName("bhvSerialization066 a null is refused for a property that is not declared nullable")
        fun nullIsRefusedForANonNullableProperty() {
            assertThrows(SerializationException::class.java) {
                serializer.deserialize<com.example.petstore.models.Pet>("{\"name\":null,\"photoUrls\":[]}")
            }
        }

        @Test
        @DisplayName("bhvSerialization009 a value that cannot be serialized raises the serialization error before any output")
        fun unserializableValueRaisesBeforeAnyOutput() {
            assertThrows(SerializationException::class.java) {
                serializer.serialize(mapOf("a" to 1, "b" to Double.NaN))
            }
        }

        @Test
        @DisplayName("bhvSerialization012 keys of maps are written in ascending order so equal data writes identical output")
        fun mapKeysAreWrittenInAscendingOrder() {
            assertEquals("{\"a\":1,\"b\":2,\"c\":3}", serializer.serialize(linkedMapOf("c" to 3, "a" to 1, "b" to 2)))
        }

        @Test
        @DisplayName("bhvSerialization062 a base64 string for a byte-typed value decodes to the raw bytes it encodes")
        fun base64StringDecodesToRawBytes() {
            assertArrayEquals(byteArrayOf(1, 2, 3), serializer.deserialize<ByteArray>("\"AQID\""))
        }
    }

    @Nested
    @DisplayName("NativeValueFormatTests")
    inner class NativeValueFormatTests {
        private fun decode(json: String) = serializer.deserialize<com.example.petstore.models.NativeValues>(json)!!

        @Test
        @DisplayName("bhvSerializationobject403 a duration field is the native java.time.Duration")
        fun durationIsTheNativeType() {
            val wait: java.time.Duration? = decode("{\"wait\":\"3600s\"}").wait
            assertEquals(java.time.Duration.ofHours(1), wait)
        }

        @Test
        @DisplayName("bhvSerializationobject404 a duration keeps every nanosecond the type holds and writes the shortest form")
        fun durationKeepsEveryNanosecond() {
            val decoded = decode("{\"wait\":\"-1.123456789s\"}")
            assertEquals(java.time.Duration.ofSeconds(-1, -123456789), decoded.wait)
            assertEquals("{\"wait\":\"-1.123456789s\"}", serializer.serialize(decoded))
        }

        @Test
        @DisplayName("bhvSerializationobject405 an ipv4 field keeps the address text unchanged")
        fun ipv4TextRoundTrips() {
            assertEquals("{\"address4\":\"192.0.2.1\"}", serializer.serialize(decode("{\"address4\":\"192.0.2.1\"}")))
        }

        @Test
        @DisplayName("bhvSerializationobject406 an ipv6 field keeps the address text unchanged")
        fun ipv6TextRoundTrips() {
            for (text in listOf("2001:0DB8:0:0:0:0:0:1", "2001:db8::1", "::1")) {
                assertEquals("{\"address6\":\"$text\"}", serializer.serialize(decode("{\"address6\":\"$text\"}")))
            }
        }

        @Test
        @DisplayName("bhvSerializationobject408 every absolute URI of the corpus round-trips byte for byte")
        fun uriCorpusRoundTrips() {
            val corpus =
                listOf(
                    "https://example.com",
                    "HTTP://EXAMPLE.com:80/a%2fb?x=1&x=2#frag",
                    "mailto:a@b.c",
                    "urn:isbn:0451450523",
                    "https://example.com?",
                    "https://example.com/%7euser",
                    "https://[2001:db8::1]:8443/",
                )
            for (text in corpus) {
                val json = "{\"homepage\":\"$text\"}"
                assertEquals(json, serializer.serialize(decode(json)), text)
            }
            val homepage: java.net.URI? = decode("{\"homepage\":\"https://example.com\"}").homepage
            assertEquals("https://example.com", homepage.toString())
        }

        @Test
        @DisplayName("bhvSerializationobject409 hostname and email values are kept as given")
        fun hostnameAndEmailAreKept() {
            val json = "{\"host\":\"not a host!\",\"contact\":\"x@\"}"
            assertEquals(json, serializer.serialize(decode(json)))
        }

        @Test
        @DisplayName("bhvSerializationobject410 a number keeps every digit and is written in plain notation")
        fun numberKeepsEveryDigit() {
            val json = "{\"amount\":12.345678901234567890123}"
            val decoded = decode(json)
            assertEquals(java.math.BigDecimal("12.345678901234567890123"), decoded.amount)
            assertEquals(json, serializer.serialize(decoded))
        }

        @Test
        @DisplayName("bhvSerializationobject411 a string decimal is a BigDecimal written as a JSON string and rejects a number")
        fun stringDecimalIsAJsonString() {
            val decoded = decode("{\"ledger\":\"12.50\"}")
            assertEquals(java.math.BigDecimal("12.50"), decoded.ledger)
            assertEquals("{\"ledger\":\"12.50\"}", serializer.serialize(decoded))
            assertThrowsExactly(SerializationException::class.java) { decode("{\"ledger\":12.50}") }
        }

        @Test
        @DisplayName("bhvSerializationobject412 a forty digit number is exact and never rounded")
        fun fortyDigitNumberIsExact() {
            val digits = "1234567890123456789012345678901234567890"
            val decoded = decode("{\"amount\":$digits}")
            assertEquals(java.math.BigDecimal(digits), decoded.amount)
            assertEquals("{\"amount\":$digits}", serializer.serialize(decoded))
        }

        @Test
        @DisplayName("bhvSerializationparam104 a duration parameter is written in the protobuf form")
        fun durationParameter() {
            assertEquals("3600s", serializer.stringify(java.time.Duration.ofHours(1)))
        }

        @Test
        @DisplayName("bhvSerializationparam105 an address parameter is its text unchanged")
        fun addressParameterIsUnchanged() {
            assertEquals("2001:db8::1", serializer.stringify("2001:db8::1"))
        }

        @Test
        @DisplayName("bhvSerializationparam106 a decimal parameter is written in plain notation")
        fun decimalParameterIsPlain() {
            assertEquals("12.345678901234567890123", serializer.stringify(java.math.BigDecimal("12.345678901234567890123")))
            assertEquals("1000", serializer.stringify(java.math.BigDecimal("1E+3")))
        }
    }

    @Nested
    @DisplayName("EnumMemberNameTests")
    inner class EnumMemberNameTests {
        private fun modelSource(name: String): String =
            java.io
                .File(
                    "src/main/kotlin/" + "com.example.petstore.models".replace('.', '/') + "/" + name + ".kt",
                ).readText()

        @Test
        @DisplayName("bhvEnums001 a string enum member named by an array exposes the given name and its wire value")
        fun arrayNamesAStringMember() {
            assertEquals("s", com.example.petstore.models.Tier.SMALL.value)
            assertEquals("m", com.example.petstore.models.Tier.MEDIUM.value)
            assertEquals("l", com.example.petstore.models.Tier.LARGE.value)
            assertEquals(
                com.example.petstore.models.Tier.MEDIUM,
                serializer.deserialize<com.example.petstore.models.Subscription>("{\"rank\":1,\"tier\":\"m\"}")!!.tier,
            )
        }

        @Test
        @DisplayName("bhvEnums002 an integer enum member named by an array exposes the given name and its number")
        fun arrayNamesAnIntegerMember() {
            assertEquals(1, com.example.petstore.models.Rank.LOW.value)
            assertEquals(2, com.example.petstore.models.Rank.MEDIUM.value)
            assertEquals(3, com.example.petstore.models.Rank.HIGH.value)
            val decoded = serializer.deserialize<com.example.petstore.models.Subscription>("{\"rank\":3}")!!
            assertEquals(com.example.petstore.models.Rank.HIGH, decoded.rank)
            assertTrue(serializer.serialize(decoded).contains("\"rank\":3"))
        }

        @Test
        @DisplayName("bhvEnums003 an enum named by an object keyed by wire value names the members it lists")
        fun objectNamesTheListedMembers() {
            assertEquals("paused", com.example.petstore.models.Stage.ON_HOLD.value)
            assertEquals(
                com.example.petstore.models.Stage.ON_HOLD,
                serializer.deserialize<com.example.petstore.models.Subscription>("{\"rank\":1,\"stage\":\"paused\"}")!!.stage,
            )
            assertEquals(
                com.example.petstore.models.Stage.ACTIVE,
                serializer.deserialize<com.example.petstore.models.Subscription>("{\"rank\":1,\"stage\":\"active\"}")!!.stage,
            )
        }

        @Test
        @DisplayName("bhvEnums004 a supplied name that is not a legal identifier is cleaned and cased")
        fun suppliedNameIsCleanedAndCased() {
            assertEquals(
                "paused",
                com.example.petstore.models.Stage
                    .valueOf("ON_HOLD")
                    .value,
            )
        }

        @Test
        @DisplayName("bhvEnums005 two supplied names that collide after casing keep distinct names and wires")
        fun collidingNamesStayDistinct() {
            assertEquals(
                "active",
                com.example.petstore.models.Stage
                    .valueOf("ACTIVE")
                    .value,
            )
            assertEquals(
                "live",
                com.example.petstore.models.Stage
                    .valueOf("ACTIVE2")
                    .value,
            )
            assertEquals(
                com.example.petstore.models.Stage
                    .valueOf("ACTIVE2"),
                serializer.deserialize<com.example.petstore.models.Subscription>("{\"rank\":1,\"stage\":\"live\"}")!!.stage,
            )
        }

        @Test
        @DisplayName("bhvEnums006 an inline property enum takes its member names from its own keys")
        fun inlineEnumTakesItsOwnNames() {
            assertEquals("month", com.example.petstore.models.Subscription.IntervalEnum.MONTHLY.value)
            assertEquals("year", com.example.petstore.models.Subscription.IntervalEnum.YEARLY.value)
        }

        @Test
        @DisplayName("bhvEnums007 a default on a referenced enum property starts at the member with the supplied name")
        fun defaultStartsAtTheSuppliedMember() {
            assertEquals(
                com.example.petstore.models.Tier.MEDIUM,
                com.example.petstore.models
                    .Subscription(rank = com.example.petstore.models.Rank.LOW)
                    .tier,
            )
            assertEquals(
                com.example.petstore.models.Tier.MEDIUM,
                serializer.deserialize<com.example.petstore.models.Subscription>("{\"rank\":1}")!!.tier,
            )
        }

        @Test
        @DisplayName("bhvEnums008 encoding writes the wire value and decoding rejects a supplied name")
        fun wireValueOnlyOnTheWire() {
            assertEquals("\"m\"", serializer.serialize(com.example.petstore.models.Tier.MEDIUM))
            val error =
                assertThrows(SerializationException::class.java) {
                    serializer.deserialize<com.example.petstore.models.Subscription>("{\"rank\":1,\"tier\":\"Medium\"}")
                }
            assertTrue(error.message!!.contains("Medium"), error.message)
        }

        @Test
        @DisplayName("bhvEnums009 a member with a description carries it as the one-line comment directly above it")
        fun descriptionIsTheCommentAboveTheMember() {
            assertTrue(modelSource("Tier").contains("/** The smallest tier. */\n  @SerialName(\"s\")\n  SMALL("))
            assertTrue(modelSource("Tier").contains("/** The medium tier. */\n  @SerialName(\"m\")\n  MEDIUM("))
        }

        @Test
        @DisplayName("bhvEnums010 a member without a description keeps the comment it has today")
        fun undescribedMemberKeepsItsComment() {
            assertFalse(modelSource("Rank").contains("/** The"))
            assertTrue(modelSource("Rank").contains("  MEDIUM(2)"))
        }

        @Test
        @DisplayName("bhvEnums011 a description with comment terminators still yields a compiling comment")
        fun hostileDescriptionStaysAComment() {
            val source = modelSource("Tier")
            assertTrue(source.contains("/** The largest tier. Ends with * / and #{x} and \$x. */\n  @SerialName(\"l\")"))
        }
    }
}

// File-scoped fixture: a property whose wire name begins with a digit.
@Serializable
private data class DigitLeadingName(
    @SerialName("2fa")
    val twoFa: String? = null,
)
